private bool ReadExcel()
{
    try
    {
        SIM_RegisterDorm obj = new SIM_RegisterDorm();
        DataTable dtbStudent = obj.GetDataTable("SIM_Student_GetAllSimple");

        if (dtbStudent == null || dtbStudent.Rows.Count == 0)
        {
            MessageManager.Error("Không thể tải danh sách sinh viên! " + (obj.ErrorException != null ? obj.ErrorException.Message : ""));
            return false;
        }

        int importCount = gvData.ImportFromExcel("Mã SV", "");
        if (importCount <= 0)
        {
            MessageManager.Error("Không có dữ liệu nào được nhập từ file Excel!");
            return false;
        }

        int invalidCount = 0;
        StringBuilder sbInvalid = new StringBuilder();

        foreach (DataRow drw in dtbData.Rows)
        {
            if (drw.RowState != DataRowState.Deleted && Convert.ToBoolean(drw["IsEdit"]))
            {
                string studentCode = drw["StudentCode"].ToString().Trim();

                if (studentCode != "")
                {
                    DataRow[] rows = dtbStudent.Select("StudentCode = '" + studentCode.Replace("'", "''") + "'");
                    if (rows.Length > 0)
                    {
                        drw["StudentID"] = rows[0]["StudentID"];
                        drw["IsValid"] = true;
                    }
                    else
                    {
                        // Không tồn tại sinh viên
                        drw["StudentID"] = DBNull.Value;
                        drw["IsValid"] = false;
                        invalidCount++;

                        // Gom mã sinh viên không tồn tại
                        sbInvalid.AppendLine(studentCode);
                    }
                }
            }
        }

        gvData.BestFitColumns();

        //  Ghi log 1 lần nếu có sinh viên không tồn tại
        if (invalidCount > 0)
        {
            string strActionLog = 
                                  sbInvalid.ToString();

            new SystemObject.SYS_ActionLog().WriteActionLog(
                "Import hồ sơ sinh viên (không tồn tại)",
                strActionLog,
                SystemObject.ActionLogType.ADD, 
                1,
                UserSession.Username
            );

            MessageManager.Warning("Có " + invalidCount.ToString() + " sinh viên không tồn tại. Hệ thống đã ghi log chi tiết.");
        }

        return true;
    }
    catch (Exception ex)
    {
        MessageManager.Error("Lỗi khi đọc dữ liệu từ Excel:\r\n" + ex.Message);
        return false;
    }
}



