private bool SaveData()
{
    SIM_RegisterDorm obj = new SIM_RegisterDorm();
    obj.BeginTransaction();

    try
    {
        foreach (DataRow drw in dtbData.Rows)
        {
            // Bỏ qua dòng không hợp lệ hoặc chưa chỉnh sửa
            if (drw.RowState == DataRowState.Deleted || !Convert.ToBoolean(drw["IsEdit"]))
                continue;

            if (drw.Table.Columns.Contains("IsValid") && drw["IsValid"] != DBNull.Value && Convert.ToBoolean(drw["IsValid"]) == false)
                continue;

            SIM_RegisterDorm item = new SIM_RegisterDorm();
            item.IDB = obj.IDB;

            // Parse dữ liệu từ dòng
            if (item.Parse(drw))
            {
                if (drw["StudentID"] == DBNull.Value)
                    continue;

                item.StudentID = Convert.ToInt64(drw["StudentID"]);
                item.StartDate = DateTime.Now;
                item.EndDate = DateTime.Now;
                item.RegisterDormType = 1;
                item.IsLeft = false;
                item.Description = "";

                if (item.RegisterDormID != null && Convert.ToInt64(item.RegisterDormID) > 0)
                {
                    // Cập nhật
                    item.UpdatedUser = UserSession.Username;
                    if (!item.Update())
                        throw new Exception("Lỗi cập nhật tại sinh viên: " + drw["StudentCode"].ToString() +
                            "\r\nChi tiết: " + item.ErrorException.Message);
                }
                else
                {
                    // Thêm mới
                    item.CreatedUser = UserSession.Username;
                    if (!item.Add())
                        throw new Exception("Lỗi thêm mới tại sinh viên: " + drw["StudentCode"].ToString() +
                            "\r\nChi tiết: " + item.ErrorException.Message);
                }
            }
            else
            {
                throw new Exception("Không thể đọc thông tin từ dòng dữ liệu: " + drw["StudentCode"].ToString());
            }
        }

        obj.CommitTransaction();
        MessageManager.Info("Lưu dữ liệu thành công!");
        return true;
    }
    catch (Exception ex)
    {
        obj.RollBackTransaction();
        ErrorManager.Error("Lỗi trong quá trình lưu dữ liệu:\r\n" + ex.Message);
        return false;
    }
}

private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
{
