    if (drw != null)
    {
        drw["IsEdit"] = true;

    }
}

private void gvData_RowCellStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowCellStyleEventArgs e)
{
    DataRow drw = gvData.GetDataRow(e.RowHandle);
    if (drw != null)
    {
        if (Convert.ToBoolean(drw["IsEdit"]))
        {
            if (drw["StudentID"].ToString() == "")
                e.Appearance.BackColor = Color.LightGreen; // thêm
            else
                e.Appearance.BackColor = Color.LightPink; // sửa
        }
    }
}

